    let workspace = CompilerWorkspace::new(repo_root);
    let relative_path = workspace
        .normalize_repo_relative(relative_path)
        .map_err(RepoRelativeFileAccessError::InvalidPath)?;
    workspace.read_string(&relative_path)
}

